      }
    ],
    "lacunas": [
      "A ficha d_a70f, indicada como contendo todas as precedências, não está disponível na view; não é possível determinar o efeito da redução da duração do dossiê no término do projeto."
    ],
    "motivo": "O aviso reduz a duração do dossiê, mas faltam as precedências necessárias para calcular o término atualizado.",
    "unidade": "dia_corrido"
  },
  "delta_dias": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_d7254f",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_36c2",
        "localizador": "L02"
      }
    ],
    "lacunas": [
      "Sem as precedências, não se sabe se a atividade reduzida determina o término nem qual seria a variação."
    ],
    "motivo": "A magnitude e a direção da variação do término não podem ser estabelecidas com os dados visíveis.",
    "unidade": "dia_corrido"
  },
  "custo_base": {
    "estado": "exato",
    "valor": 165000,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_36c2",
        "localizador": "L02"
      }
    ],
    "lacunas": [],
    "motivo": "Custo total da linha base declarado como R$ 1.650,00.",
    "unidade": "BRL_centavo"
  },
  "custo_novo": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_d7254f",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_493d",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_b915",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_36c2",
        "localizador": "L02"
      }
    ],
    "lacunas": [
      "O crédito autorizado recalcula a extensão do apoio conforme o término final, que não pode ser determinado sem as precedências."
    ],
    "motivo": "As parcelas fixas permanecem, mas o apoio pode variar com a extensão; o término necessário para calcular esse ajuste é indeterminado.",
    "unidade": "BRL_centavo"
  },
  "delta_centavos": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_d7254f",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_493d",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_36c2",
        "localizador": "L02"
      }
    ],
    "lacunas": [
      "Não é possível calcular o custo novo sem determinar o término final e a extensão recalculada do apoio."
    ],
    "motivo": "A variação do custo depende do ajuste de apoio condicionado ao término atualizado.",
    "unidade": "BRL_centavo"
  },
  "justificativa": "O aviso reduz a duração do dossiê e autoriza crédito na extensão do apoio, mas a view não contém as precedências que a fonte f_36c2 L02 atribui à ficha d_a70f. Sem essa informação, não se pode determinar o impacto no término nem o custo recalculado."
}

